const crypto = require('crypto');

// Ulaz: ceo zahtev koji je Webhook primio (headers + body)
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};

// 1) Da li postoji sve što nam treba? (u n8n-u su nazivi zaglavlja malim slovima)
const ts = headers['x-relay-timestamp'];
const sig = headers['x-relay-signature'];
const eventId = body.eventId;
if (!ts || !sig || !eventId || !/^\d+$/.test(ts)) {
  return [{ json: { valid: false, error: 'bad_request' } }];
}

// 2) Da li je zahtev svež? (najviše 5 minuta razlike)
if (Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) {
  return [{ json: { valid: false, error: 'stale_timestamp' } }];
}

// 3) Izračunaj potpis istim receptom kao aplikacija: HMAC-SHA256(secret, "ts.eventId")
const secret = $env.N8N_SHARED_SECRET;
if (!secret) throw new Error('N8N_SHARED_SECRET nije podešen');
const expected = crypto.createHmac('sha256', secret).update(`${ts}.${eventId}`).digest('hex');

// 4) Uporedi bez curenja vremena. timingSafeEqual puca ako dužine nisu iste, pa prvo to proveri.
const a = Buffer.from(expected);
const b = Buffer.from(String(sig).toLowerCase());
const ok = a.length === b.length && crypto.timingSafeEqual(a, b);

return [{ json: ok ? { valid: true } : { valid: false, error: 'invalid_signature' } }];
